import{_ as l}from"./plugin-vue_export-helper-c27b6911.js";import{r as s,o as r,c as i,b as t,d as e,a,w as d,f as p,e as c}from"./app-2ff98964.js";const u={},h=t("h1",{id:"一台-20-的-vps-养着我的数字乐园",tabindex:"-1"},[t("a",{class:"header-anchor",href:"#一台-20-的-vps-养着我的数字乐园","aria-hidden":"true"},"#"),e(" 一台 $20 的 VPS，养着我的数字乐园")],-1),k=t("p",null,"以前我的服务挂了，是用户来告诉我的。现在是手机先响。",-1),b=t("p",null,"这篇记录一下，我是怎么用一堆开源服务，把一台小 VPS 打理成一个自己的数字乐园的。",-1),f=t("blockquote",null,[t("p",null,"文中的域名、IP、密钥都用占位符代替。")],-1),_=t("h2",{id:"全景",tabindex:"-1"},[t("a",{class:"header-anchor",href:"#全景","aria-hidden":"true"},"#"),e(" 全景")],-1),g=t("p",null,"先看一眼现在这台机器上都有什么：",-1),m=t("thead",null,[t("tr",null,[t("th",null,"层"),t("th",null,"用什么"),t("th",null,"干什么")])],-1),v=t("td",null,"部署",-1),q={href:"https://coolify.io",target:"_blank",rel:"noopener noreferrer"},C=t("td",null,"所有应用和数据库，push 代码自动部署",-1),y=t("tr",null,[t("td",null,"门禁"),t("td",null,"Cloudflare Zero Trust"),t("td",null,"管理后台要先登录，服务器只认 Cloudflare 来的流量")],-1),x=t("td",null,"监控",-1),S={href:"https://github.com/lyc8503/UptimeFlare",target:"_blank",rel:"noopener noreferrer"},$={href:"https://github.com/henrygd/beszel",target:"_blank",rel:"noopener noreferrer"},G=t("td",null,"服务在不在线；CPU、内存、磁盘",-1),U=t("td",null,"定时任务",-1),M={href:"https://github.com/healthchecks/healthchecks",target:"_blank",rel:"noopener noreferrer"},P=t("td",null,"每天的备份、重启、清理有没有按时跑",-1),T=t("td",null,"告警",-1),A={href:"https://ntfy.sh",target:"_blank",rel:"noopener noreferrer"},I=t("td",null,"上面所有告警汇到一个地方，推到手机",-1),L=t("td",null,"备份",-1),w={href:"https://github.com/garethgeorge/backrest",target:"_blank",rel:"noopener noreferrer"},B=t("td",null,"数据库、密码库、整机配置，每天加密传到 R2",-1),V=t("td",null,"入口",-1),H={href:"https://github.com/glanceapp/glance",target:"_blank",rel:"noopener noreferrer"},N=t("td",null,"一个导航页，看一眼就知道全局",-1),R=t("td",null,"统计",-1),E={href:"https://umami.is",target:"_blank",rel:"noopener noreferrer"},D=t("td",null,"网站访问统计",-1),z=t("td",null,"密码",-1),O={href:"https://github.com/dani-garcia/vaultwarden",target:"_blank",rel:"noopener noreferrer"},F=t("td",null,"自建的 Bitwarden",-1),Q=c(`<p>全部是开源软件，除了 VPS 本身每月 $20，没有多花一分钱。R2 用的是免费额度。</p><h2 id="门禁-后台只有我能进" tabindex="-1"><a class="header-anchor" href="#门禁-后台只有我能进" aria-hidden="true">#</a> 门禁：后台只有我能进</h2><p>Coolify 面板、状态页、导航页、备份管理页，这些地方只有我自己需要看，没必要对整个互联网开放。</p><p>我的做法是三层：</p><ol><li><strong>域名开 Cloudflare 代理</strong>（橙色云朵），流量先过 Cloudflare。</li><li><strong>加一层 Zero Trust Access。</strong> 打开页面先跳到 Cloudflare 的登录页，用 GitHub 账号或者邮箱验证码登录，名单里只有我自己的几个邮箱。免费版 50 人以内不收钱。</li><li><strong>服务器只认 Cloudflare 的 IP。</strong> 不然别人知道了服务器 IP，绕过 Cloudflare 直接连，前两层就白搭了。我在 Traefik 里加了一个 <code>ipAllowList</code> 中间件，只放行 Cloudflare 公布的 IP 段，直连一律 403。</li></ol><p>有两个地方要特意放行：Coolify 的 <code>/webhooks</code>（GitHub 推代码后通知部署）和 <code>/api</code>（CI 和我自己调接口）。GitHub 没法帮你登录 Zero Trust，这两个路径要单独设成&quot;免登录&quot;。它们本身有签名或 Token 校验，不会因此变得不安全。</p><blockquote><p>坑：<strong>Docker 映射出去的端口会绕过 ufw。</strong> <code>ufw status</code> 显示只开了 22，但 Coolify 的 8000 端口其实一直对公网开着，任何人都能打开登录页。要在 <code>DOCKER-USER</code> 链里单独挡掉，并且写成开机自动执行。</p></blockquote><h2 id="告警-所有声音汇成一条河" tabindex="-1"><a class="header-anchor" href="#告警-所有声音汇成一条河" aria-hidden="true">#</a> 告警：所有声音汇成一条河</h2><p>监控工具我装了好几个，但手机上只装一个 App：<strong>ntfy</strong>。</p><p>ntfy 是一个极简的推送服务：往一个地址 POST 一段文字，手机就会收到通知。我自建了一个，关掉注册、默认谁都不能读写，只建了两个账号：一个给手机看，一个只能往 <code>alerts</code> 主题里写，给各个监控工具用。</p><p>现在往这条河里汇水的有四个源头：</p><table><thead><tr><th>谁</th><th>什么时候响</th></tr></thead><tbody><tr><td>UptimeFlare</td><td>某个网站打不开，或者恢复了</td></tr><tr><td>Beszel</td><td>服务器离线；CPU、内存连续 10 分钟超过 90%；磁盘超过 85%</td></tr><tr><td>Healthchecks</td><td>某个定时任务没按时跑，或者跑失败了</td></tr><tr><td>Coolify</td><td>部署失败、备份失败、容器挂了、服务器连不上</td></tr></tbody></table><p>几个小技巧：</p><ul><li><strong>UptimeFlare 跑在 Cloudflare Workers 上</strong>，不在被监控的机器上。服务器整台挂了，它照样能发出告警。</li><li><strong>ntfy 的 token 不要写进仓库。</strong> 我在 GitHub Actions 部署时用 secret 替换配置里的占位符。</li><li><strong>Coolify 的 webhook 不能自定义请求头</strong>，就把 token 放进 URL 的 <code>auth=</code> 参数里，再用 ntfy 的消息模板把 JSON 渲染成人能读的标题和正文。</li><li><strong>iOS 的即时推送</strong>要设置 <code>upstream-base-url: https://ntfy.sh</code>。只会把消息 ID 发给官方服务器，内容不会经过它。</li></ul><h2 id="定时任务-没响也是一种告警" tabindex="-1"><a class="header-anchor" href="#定时任务-没响也是一种告警" aria-hidden="true">#</a> 定时任务：没响也是一种告警</h2><p>服务挂了会报错，但<strong>定时任务没跑，是不会报错的</strong>。备份脚本因为某次改动悄悄不执行了，你可能要等到真正需要恢复的那天才知道。</p><p>Healthchecks 解决的就是这个问题，思路叫&quot;死人开关&quot;：每个任务跑完都要来&quot;打个卡&quot;，到点没打卡就告警。</p><p>我写了一个很小的包装脚本 <code>hc-run</code>，任何定时任务套一层就行：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token shebang important">#!/bin/sh</span>
<span class="token comment"># 用法：hc-run &lt;检查名&gt; &lt;命令...&gt;</span>
<span class="token assign-left variable">slug</span><span class="token operator">=</span><span class="token variable">$1</span><span class="token punctuation">;</span> <span class="token builtin class-name">shift</span>
<span class="token assign-left variable">url</span><span class="token operator">=</span><span class="token string">&quot;https://hc.example.com/ping/<span class="token variable"><span class="token variable">$(</span><span class="token function">awk</span> <span class="token parameter variable">-v</span> <span class="token assign-left variable">s</span><span class="token operator">=</span><span class="token string">&quot;<span class="token variable">$slug</span>&quot;</span> <span class="token string">&#39;$1==s{print $2}&#39;</span> /root/.secrets/hc-checks<span class="token variable">)</span></span>&quot;</span>
<span class="token function">curl</span> <span class="token parameter variable">-fsS</span> <span class="token parameter variable">-m</span> <span class="token number">10</span> <span class="token parameter variable">-o</span> /dev/null <span class="token string">&quot;<span class="token variable">$url</span>/start&quot;</span>
<span class="token assign-left variable">out</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span>mktemp<span class="token variable">)</span></span><span class="token punctuation">;</span> <span class="token string">&quot;<span class="token variable">$@</span>&quot;</span> <span class="token operator">&gt;</span><span class="token string">&quot;<span class="token variable">$out</span>&quot;</span> <span class="token operator"><span class="token file-descriptor important">2</span>&gt;</span><span class="token file-descriptor important">&amp;1</span><span class="token punctuation">;</span> <span class="token assign-left variable">rc</span><span class="token operator">=</span><span class="token variable">$?</span>
<span class="token function">cat</span> <span class="token string">&quot;<span class="token variable">$out</span>&quot;</span>
<span class="token function">tail</span> <span class="token parameter variable">-c</span> <span class="token number">10000</span> <span class="token string">&quot;<span class="token variable">$out</span>&quot;</span> <span class="token operator">|</span> <span class="token function">curl</span> <span class="token parameter variable">-fsS</span> <span class="token parameter variable">-m</span> <span class="token number">10</span> <span class="token parameter variable">-o</span> /dev/null --data-binary @- <span class="token string">&quot;<span class="token variable">$url</span>/<span class="token variable">$rc</span>&quot;</span>
<span class="token function">rm</span> <span class="token parameter variable">-f</span> <span class="token string">&quot;<span class="token variable">$out</span>&quot;</span><span class="token punctuation">;</span> <span class="token builtin class-name">exit</span> <span class="token variable">$rc</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>它会上报开始、退出码和最后一段输出，失败时在通知里就能直接看到报错。</p><p>现在被盯着的任务有：每天重启一个吃内存的前端、清理过期的快照数据、备份密码库、导出数据库、整机备份，还有一个专门检查&quot;Coolify 的数据库备份到底有没有成功传到 R2&quot;的任务。</p><blockquote><p>坑：<strong>Coolify 的定时任务按服务器时区（UTC）跑</strong>，不是你在设置里选的时区。我一开始以为备份在凌晨，其实是中午。Healthchecks 里每个检查的时区要对上，不然会天天误报。</p></blockquote><h2 id="备份-三层-而且要能解开" tabindex="-1"><a class="header-anchor" href="#备份-三层-而且要能解开" aria-hidden="true">#</a> 备份：三层，而且要能解开</h2><table><thead><tr><th>内容</th><th>怎么备份</th><th>保留</th></tr></thead><tbody><tr><td>PostgreSQL</td><td>Coolify 自带的定时备份，<code>pg_dumpall</code> 传到 R2</td><td>30 份</td></tr><tr><td>密码库</td><td>自己写的脚本：SQLite 在线 <code>.backup</code>，先做完整性检查再上传</td><td>30 天</td></tr><tr><td>整台机器的配置和密钥</td><td>Backrest（restic 的网页版），加密、增量、去重</td><td>日 14 / 周 8 / 月 6</td></tr></tbody></table><p>前两层是&quot;数据&quot;，第三层是&quot;环境&quot;：<code>/etc</code> 里的防火墙规则和定时任务、我写的脚本、Coolify 自己的配置和主密钥、各个服务的数据卷、所有自动生成的密码。服务器真没了，有这一份就能照着重建。</p><p>几个经验：</p><ul><li><strong>Vaultwarden 的数据不在数据库备份里。</strong> 它用的是 SQLite，存在 Docker 数据卷中，Coolify 不会备份它。我检查的时候才发现，自己的密码库其实一直在裸奔。</li><li><strong>运行中的数据库不要直接拷文件。</strong> 先 <code>pg_dumpall</code> 导出成文件，再让 Backrest 备份导出文件，恢复时才可靠。</li><li><strong>加密备份的密码一定要另存一份。</strong> restic 的仓库密码只在服务器上的话，服务器一丢，R2 里的备份也就打不开了。一定要在密码库里另存一份。</li><li><strong>上传完要验证。</strong> 第一次备份完，我把快照里的文件列表列出来对了一遍，确认密钥、数据库导出都在里面。</li></ul><h2 id="导航页-一眼看全局" tabindex="-1"><a class="header-anchor" href="#导航页-一眼看全局" aria-hidden="true">#</a> 导航页：一眼看全局</h2><p>服务多了，光记地址就够累的。我用 Glance 做了一个导航页：</p><ul><li>中间是所有服务的在线状态和响应时间，每分钟刷新；</li><li>左边是时钟（服务器所在时区、UTC、另一台机器所在时区）、加密货币行情、各个平台后台的入口；</li><li>右边是这些开源软件的最新版本，方便判断要不要升级；</li><li>顶部一个搜索框，按 <code>S</code> 聚焦，<code>!gh</code> 搜 GitHub、<code>!bd</code> 搜百度。</li></ul><p>Glance 只占 13M 内存，整个页面就是一个 YAML 文件，改完保存几秒自动生效。</p><p>默认样式是全等宽字体，中文显得歪歪扭扭。我加了一个自定义 CSS：正文换成 Inter 加系统中文字体，数字保留等宽；卡片改成大圆角、半透明、柔和阴影；再配一套明暗主题。改动不大，观感差别很明显。</p><blockquote><p>坑：</p><ul><li>Yahoo 的加密货币 24 小时涨跌一直显示 0%，我把行情换成了 CoinGecko 的免费接口，用 Glance 的 <code>custom-api</code> 组件自己写模板。</li><li>CoinGecko 的图片 CDN 在国内打不开，币种图标要下载到服务器上自己托管。</li><li>Glance 模板读数字时，YAML 里的整数会被当成 0，要写成 <code>60.0</code> 这种小数。</li></ul></blockquote><h2 id="访问日志-没有日志-出事就是瞎子" tabindex="-1"><a class="header-anchor" href="#访问日志-没有日志-出事就是瞎子" aria-hidden="true">#</a> 访问日志：没有日志，出事就是瞎子</h2><p>有一次排查一个公开的高危漏洞，想确认自己的服务有没有被打过，结果发现 Traefik 根本没开访问日志，只能靠别的痕迹间接判断。</p><p>于是我开了访问日志：JSON 格式，只留 User-Agent 和 Cloudflare 传过来的访客真实 IP，其他请求头全部丢掉。每天大约 40M，保留 7 天，压缩后一共不到 100M。</p><p>日志里会有带 token 的 URL，所以它只有 root 能读，也不进备份。</p><blockquote><p>坑：<strong>改 Coolify 的代理配置不要直接 <code>docker compose up</code> 重建容器。</strong> 重建后 Traefik 只连着主网络，各个服务自己的 Docker 网络全断了，好几个服务挂了三分钟。要通过 Coolify 的界面或者它的保存函数来改，它会把网络重新接好。</p></blockquote><h2 id="给-ai-留一份说明书" tabindex="-1"><a class="header-anchor" href="#给-ai-留一份说明书" aria-hidden="true">#</a> 给 AI 留一份说明书</h2><p>这些东西大部分是 Claude Code 帮我搭的。问题是：下次换一个会话，或者换一个 AI，它什么都不知道，很容易重复踩坑，甚至把之前的配置改坏。</p><p>所以我在服务器上放了一份 <code>/root/AGENTS.md</code>，再链接一份 <code>CLAUDE.md</code>，这是很多 AI 编程工具约定俗成的说明书文件名。SSH 登录时还会多一行提示：「先读 /root/AGENTS.md，改动后请更新它。」</p><p>里面写着：</p><ul><li>硬性规矩：不能打印密钥、不开云厂商的备份、往个人仓库提交只能用匿名邮箱；</li><li>每个服务的位置、域名和内存上限；</li><li>告警和备份链路；</li><li>每种密钥放在哪个文件里（只写位置，不写内容）；</li><li>踩过的十几个坑；</li><li>待办，以及变更记录。</li></ul><p>这份文件对人也一样有用。半年后的我，大概也不记得当初为什么要加那条防火墙规则了。</p><h2 id="第二台机器也管起来" tabindex="-1"><a class="header-anchor" href="#第二台机器也管起来" aria-hidden="true">#</a> 第二台机器也管起来</h2><p>我还有一台跑代理的小机器，1G 内存。它也接进了这套体系：</p><ul><li><strong>Beszel 的 agent</strong> 装成一个 systemd 服务，主动连回东京的 hub，不用在小机器上开任何端口；</li><li><strong>加进了 Coolify</strong>，但代理类型设成 None，因为 443 已经被代理程序占了，不能再让 Coolify 装 Traefik；</li><li>它离线、磁盘快满时，同样推到 ntfy。</li></ul><h2 id="资源和成本" tabindex="-1"><a class="header-anchor" href="#资源和成本" aria-hidden="true">#</a> 资源和成本</h2><table><thead><tr><th>服务</th><th>内存</th></tr></thead><tbody><tr><td>ntfy</td><td>15M</td></tr><tr><td>Beszel</td><td>14M（agent 另 5M）</td></tr><tr><td>Glance</td><td>13M</td></tr><tr><td>Backrest</td><td>11M</td></tr><tr><td>Healthchecks</td><td>150M</td></tr><tr><td>Umami</td><td>240M</td></tr></tbody></table><p>这一整圈&quot;看不见的东西&quot;加起来不到 500M。整台机器（2 核 4G）跑着十几个业务服务再加上它们，内存用了一半多一点，CPU 负载不到 1。</p><p>额外花费：0。</p><h2 id="最后" tabindex="-1"><a class="header-anchor" href="#最后" aria-hidden="true">#</a> 最后</h2><p>搬家那一篇解决的是&quot;放在哪&quot;，这一篇解决的是&quot;放心交出去&quot;。</p><p>我的感受是，自托管真正的成本从来不是那 $20，而是你需要随时惦记着它。这一圈服务做的事情，就是把&quot;惦记&quot;这件事外包出去：网站挂了有人喊，任务漏了有人喊，数据丢了有备份，忘了怎么回事有说明书。</p><p>现在大部分时候，我已经不用去看它了。手机不响，就说明一切正常。</p>`,55);function Y(Z,J){const o=s("RouterLink"),n=s("ExternalLinkIcon");return r(),i("div",null,[h,k,t("p",null,[e("上一篇写了"),a(o,{to:"/posts/thinking/2026/thinking/migrate-vps.html"},{default:d(()=>[e("怎么把十几个服务搬进一台 VPS")]),_:1}),e('。搬完之后，我又在这台机器上陆续搭了一圈"看不见的东西"：门禁、告警、定时任务监控、整机备份、导航页。它们不直接产生价值，但有了它们，这台机器才算真正能放心交出去。')]),b,p(" more "),f,_,g,t("table",null,[m,t("tbody",null,[t("tr",null,[v,t("td",null,[t("a",q,[e("Coolify"),a(n)])]),C]),y,t("tr",null,[x,t("td",null,[t("a",S,[e("UptimeFlare"),a(n)]),e("、"),t("a",$,[e("Beszel"),a(n)])]),G]),t("tr",null,[U,t("td",null,[t("a",M,[e("Healthchecks"),a(n)])]),P]),t("tr",null,[T,t("td",null,[t("a",A,[e("ntfy"),a(n)])]),I]),t("tr",null,[L,t("td",null,[e("Coolify 自带、"),t("a",w,[e("Backrest"),a(n)])]),B]),t("tr",null,[V,t("td",null,[t("a",H,[e("Glance"),a(n)])]),N]),t("tr",null,[R,t("td",null,[t("a",E,[e("Umami"),a(n)])]),D]),t("tr",null,[z,t("td",null,[t("a",O,[e("Vaultwarden"),a(n)])]),F])])]),Q])}const j=l(u,[["render",Y],["__file","my-vps-monitor.html.vue"]]);export{j as default};
